import './style.css';import './testnet.css';
import {icon,esc} from './ui.js';
import {state,subscribe,emit,getProviders,connect,disconnect,autoConnect,addArcNetwork,checkNetwork,initRegistry,setRegistry,deployRegistry,loadBills,loadBill,createBill,estimatePayment,contribute,cancelBill,refundBill,sendUSDC,estimateSend,refreshWallet,EXPLORER,WC_PROJECT_ID} from './chain.js';
import {parseAmount,formatAmount as fmt,equalShare} from './amounts.js';
import {getTransfers,saveTransfer,getActions,saveAction} from './history.js';
const $=id=>document.getElementById(id);const short=a=>a?`${a.slice(0,6)}…${a.slice(-4)}`:'Not connected';
const nav=[['dashboard','grid','Overview'],['checkouts','bill','Checkouts'],['history','clock','History'],['send','arrow','Send USDC'],['refunds','shield','Refunds'],['merchant','store','Business'],['bridge','wallet','Add funds']];
const mobileNav=[['dashboard','grid','Home'],['checkouts','bill','Checkouts'],['send','arrow','Send'],['merchant','store','Business'],['more','more','More']];
let currentBill=null,routeToken=0,filter='all',paymentMode='full',poll=null,refreshing=false,lastListRefresh=0,bridgeModule=null,lastAccount=null,lastReceipt=null,detailReturnRoute='checkouts';
const profileKey=account=>`arrey-merchant-name-${account.toLowerCase()}`;
const readProfile=account=>{try{return account?localStorage.getItem(profileKey(account))||'':'';}catch{return '';}};
let merchantProfile='';
const btn=(text,action,style='primary',ic='')=>`<button class="btn ${style}" ${action?'data-action="'+action+'"':''}>${ic?icon(ic):''}${text}</button>`;
const explorer=(address,text=short(address))=>`<a class="chain-link" href="${EXPLORER}/address/${encodeURIComponent(address)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`;
const statusText=b=>({active:'Collecting',paid:'Settled',expired:'Expired',cancelled:'Cancelled'}[b.status]);
const recordConfirmed=(type,billId,amount,title,hash=state.hash,account=state.account)=>{try{return saveAction({hash,account,type,billId,amount,title});}catch{return false;}};
function landing(){
 $('app').innerHTML=`<div class="v2-page"><header class="v2-nav"><a class="v2-brand" href="#landing"><span class="v2-logo"><img src="/logo.png" width="29" height="29" alt="Arrey"></span><strong>Arrey</strong></a><nav aria-label="Main navigation"><a href="#v2-product">Product</a><a href="#v2-how">How it works</a><a href="#v2-security">Security</a></nav><div class="v2-nav-end"><span class="v2-chain"><i></i>Arc Testnet</span><a class="v2-open" href="#dashboard">Launch app ${icon('arrow')}</a></div></header><main id="main-content"><section class="v2-hero"><div class="v2-copy"><div class="v2-eyebrow"><span>Built on Arc</span><span>Powered by Circle USDC</span></div><h1>Payments,<br><em>made collective.</em></h1><p>One checkout for a customer, a team, or everyone at the table. Send, split and settle USDC without making payments feel complicated.</p><div class="v2-ctas"><a class="v2-primary" href="#dashboard">Open payment workspace ${icon('arrow')}</a><button class="v2-ghost" data-action="demo">View guided demo</button></div><div class="v2-meta"><span>${icon('shield')} Non-custodial</span><span>${icon('check')} Onchain settlement</span><span>${icon('clock')} Refund protection</span></div></div><div class="v2-stage" id="v2-product"><div class="v2-stage-bar"><span><i></i><i></i><i></i></span><b>arrey.app / checkout</b><small>ARC TESTNET</small></div><div class="v2-stage-body"><aside><span class="v2-mini-brand"><img src="/logo.png" width="22" height="22" alt="">Arrey</span><div class="v2-side-active">${icon('grid')} Overview</div><div>${icon('bill')} Checkouts</div><div>${icon('arrow')} Send USDC</div><div>${icon('wallet')} Add funds</div></aside><section><div class="v2-screen-head"><div><small>PAYMENT WORKSPACE</small><h2>Good afternoon.</h2></div><span class="v2-live"><i></i>Arc online</span></div><div class="v2-screen-actions"><div class="v2-action-main"><span>${icon('bill')}</span><small>SHARED CHECKOUT</small><strong>Create one link.<br>Collect every share.</strong><a href="#dashboard">Create checkout ${icon('arrow')}</a></div><div class="v2-action-stack"><div><span>${icon('arrow')}</span><p><small>QUICK ACTION</small><strong>Send USDC</strong></p></div><div><span>${icon('people')}</span><p><small>CONTRIBUTORS</small><strong>Full · Equal · Custom</strong></p></div></div></div><div class="v2-status-row"><span><i>01</i><b>Checkout created</b><small>Share one QR or link</small></span><em></em><span><i>02</i><b>Contributions arrive</b><small>Everyone pays their way</small></span><em></em><span><i>03</i><b>Merchant settled</b><small>Automatic at 100%</small></span></div></section></div></div></section><section class="v2-strip"><span>ARC</span><i></i><span>CIRCLE USDC</span><i></i><span>CCTP</span><i></i><span>SELF-CUSTODY</span></section><section class="v2-sections" id="v2-how"><div class="v2-section-title"><span>BUILT FOR REAL PAYMENT MOMENTS</span><h2>Simple for the payer.<br>Powerful for the merchant.</h2></div><div class="v2-bento"><article><span>01</span><h3>Pay directly</h3><p>Send Circle USDC to any Arc wallet with a clear review before signing.</p></article><article class="v2-bento-feature"><span>02</span><h3>Bring everyone together</h3><p>Create a checkout where one person can cover the bill, or everyone can contribute their part.</p><div class="v2-contributors"><b>Y</b><b>A</b><b>M</b><strong>Flexible group contributions</strong></div></article><article id="v2-security"><span>03</span><h3>Settle with confidence</h3><p>Full bills settle automatically. Cancelled or expired bills unlock individual refunds.</p></article></div></section></main><footer class="v2-footer"><a class="v2-brand" href="#landing"><span class="v2-logo"><img src="/logo.png" width="24" height="24" alt="Arrey"></span><strong>Arrey</strong></a><p>USDC payments for one, or everyone.</p><div><a href="https://docs.arc.io/" target="_blank" rel="noopener noreferrer">Arc docs</a><a href="#setup">Network</a><a href="#dashboard">Launch app</a></div></footer></div>`;updateStatus();
}
function shell(html,active='dashboard'){
 const mobileActive=['refunds','bridge','setup','history'].includes(active)?'more':active;
 $('app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#dashboard"><img src="/logo.png" width="34" height="34" alt="Arrey">Arrey<span>.</span></a><div class="workspace"><span class="avatar square">${icon('wallet')}</span><div><strong>${state.account?short(state.account):'Your wallet workspace'}</strong><br><span class="small muted">${state.chainId===5042002?'Connected to Arc':'Arc Testnet · USDC'}</span></div></div><div class="nav-label">PAYMENTS</div><nav class="nav">${nav.map(([id,ic,title])=>`<a href="#${id}" class="${id===active?'active':''}">${icon(ic)}${title}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help"><span class="eyebrow">TESTNET PREVIEW</span><p>Real transactions.<br>Test tokens only.</p><a href="https://faucet.circle.com/" target="_blank" rel="noopener noreferrer">Get free test USDC ↗</a></div><a class="settings-link" href="#setup">${icon('shield')} Network & contract</a><a class="settings-link" href="#landing">${icon('arrow')} Back to website</a></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span>/</span> <strong>${nav.find(n=>n[0]===active)?.[2]||({more:'More',setup:'Network & contract'})[active]||'Checkout'}</strong></div><a class="brand mobile-brand" href="#dashboard"><img src="/logo.png" width="28" height="28" alt="Arrey">Arrey</a><div class="top-actions"><a class="network-pill ${state.network?'ready':''}" href="#setup"><i></i><span>Arc Testnet</span><small>${state.network?'RPC online':'Checking'}</small></a><button class="btn wallet-button" data-action="wallet" id="wallet-button">${state.account?short(state.account):'Connect wallet'}</button></div></header><nav class="mobile-nav">${mobileNav.map(([id,ic,title])=>`<a href="#${id}" class="${id===mobileActive?'active':''}" aria-label="${title}">${icon(ic)}<span>${title}</span></a>`).join('')}</nav><div class="content" id="main-content"><div id="operation-banner" aria-live="polite"></div>${html}<footer class="footer"><span>Arrey · Pay solo. Pay together.</span><span>Arc Testnet · Test tokens have no monetary value</span></footer></div></main></div>`;if(active==='dashboard')document.querySelector('.stats')?.insertAdjacentHTML('beforebegin',quickActions());updateStatus();
}
function operationProgress(message){const submitted=!!state.hash,confirming=/waiting|confirming|deploying/i.test(message);return `<div class="tx-progress"><span class="done">${icon('check')}<small>Prepared</small></span><i class="${submitted?'done':''}"></i><span class="${submitted?'done current':'current'}">${submitted?icon('check'):'<b>2</b>'}<small>${submitted?'Submitted':'Wallet'}</small></span><i class="${confirming?'done':''}"></i><span class="${confirming?'current':''}"><b>3</b><small>Confirmed</small></span></div>`;}
function updateStatus(){const b=$('operation-banner');const message=state.busy?state.step:state.error;const hash=state.hash&&/^0x[a-fA-F0-9]{64}$/.test(state.hash)?`<a href="${EXPLORER}/tx/${state.hash}" target="_blank" rel="noopener noreferrer">View on ArcScan ↗</a>`:'';const content=message?`<div class="operation ${state.error&&!state.busy?'error':''}">${state.busy?'<span class="spinner"></span>':''}<span><strong>${state.error&&!state.busy?'Transaction needs attention':'Transaction in progress'}</strong><small>${esc(message)}</small></span>${hash}${state.busy?operationProgress(message):''}</div>`:'';if(b)b.innerHTML=content;const m=$('modal-status');if(m)m.innerHTML=content;const w=$('wallet-button');if(w)w.textContent=state.account?short(state.account):'Connect wallet';document.querySelectorAll('[data-financial]').forEach(el=>el.disabled=state.busy);}
subscribe(()=>{updateStatus();if(lastAccount!==state.account){lastAccount=state.account;merchantProfile=readProfile(state.account);currentBill=null;loadCurrent().catch(fail);}});
function heading(title,description,button=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${button}</div>`;}
function setupNotice(){return !state.verified?'<div class="notice">Checkout contract is not configured yet. <a href="#setup"><strong>Set up Arc checkout →</strong></a> Direct USDC transfers are available with a connected wallet.</div>':'';}
function quickActions(){return `<div class="quick-actions"><button class="featured" data-action="create"><span class="quick-icon">${icon('bill')}</span><span><strong>Create checkout</strong><small>Solo or shared payment link</small></span></button><a href="#send"><span class="quick-icon">${icon('arrow')}</span><span><strong>Send USDC</strong><small>Direct Arc payment</small></span></a><a href="#bridge"><span class="quick-icon">${icon('wallet')}</span><span><strong>Add funds</strong><small>Faucet or Circle bridge</small></span></a></div>`;}
function activityPanel(){const rows=[...state.bills].slice(0,5);return `<section class="activity-block"><div class="section-head"><div><span class="eyebrow">ONCHAIN ACTIVITY</span><h2>Recent checkout activity</h2></div>${state.account?btn('Refresh','refresh','','clock'):''}</div>${!state.account?'<div class="activity-empty">Connect your wallet to read your checkout history from Arc.</div>':!state.verified?'<div class="activity-empty">Add the checkout contract to read your shared-payment history. Direct transfers remain visible in your wallet and ArcScan.</div>':rows.length?`<div class="activity-list">${rows.map(b=>`<a href="#checkout/${b.id}"><span class="activity-symbol">${icon(b.status==='paid'?'check':b.status==='active'?'clock':'shield')}</span><span><strong>${esc(b.title)}</strong><small>${esc(b.merchantName)} · Checkout #${b.id}</small></span><span class="activity-value"><strong>${fmt(b.raised)} USDC</strong><small class="${b.status}">${statusText(b)}</small></span></a>`).join('')}</div>`:'<div class="activity-empty">No checkout activity yet. Your first confirmed checkout will appear here.</div>'}</section>`;}
function businessSetup(){return `<section class="business-start"><div><span class="eyebrow">MERCHANT SETUP</span><h2>${merchantProfile?`Welcome, ${esc(merchantProfile)}.`:'Start accepting together.'}</h2><p>${merchantProfile?'Your business profile is saved on this device. Create a checkout when you are ready.':'Add a display name, connect your wallet, and create your first QR checkout.'}</p></div>${btn(merchantProfile?'Edit business':'Set up business','onboarding','primary','store')}</section>`;}
function welcomeWorkspace(){return `<section class="welcome-workspace"><div class="welcome-copy"><span class="eyebrow">START IN UNDER A MINUTE</span><h2>Your first payment starts here.</h2><p>Connect an EVM wallet, create a checkout, then share one QR or link. Arrey handles direct and group payments on Arc.</p>${btn('Connect wallet','wallet','primary','wallet')}<button class="btn text" data-action="demo">View guided demo ${icon('arrow')}</button></div><div class="welcome-steps"><div><b>01</b><span><strong>Connect</strong><small>Add Arc Testnet automatically</small></span><em>Now</em></div><div><b>02</b><span><strong>Create</strong><small>Solo or shared checkout</small></span></div><div><b>03</b><span><strong>Share</strong><small>QR, link, or wallet address</small></span></div><div class="welcome-trust">${icon('shield')} Self-custody · Every transaction stays in your wallet</div></div></section>`;}
function demoModal(){modal('See one payment come together',`<div class="demo-label">GUIDED PRODUCT WALKTHROUGH · EXAMPLE DATA</div><div class="demo-bill"><div><span class="demo-merchant">FRIDAY DINNER</span><strong>120.00 <small>USDC</small></strong><p>Olive Kitchen · 4 people</p></div><span class="demo-qr">${icon('grid')}</span></div><div class="demo-steps"><div><b>1</b><span><strong>Create & share</strong><small>The merchant creates one bill and shares its QR.</small></span><em>120 USDC</em></div><div><b>2</b><span><strong>Everyone pays their way</strong><small>One friend pays 30, another pays 50, and someone covers 40.</small></span><em>100%</em></div><div><b>3</b><span><strong>Automatic settlement</strong><small>At the full amount, the contract sends 120 USDC to the merchant.</small></span><em>Settled</em></div></div><div class="notice">This walkthrough uses example data and does not submit a transaction.</div><button class="btn primary full" data-action="demo-open">Open the real workspace ${icon('arrow')}</button>`);}
function onboardingModal(){if(!state.account){walletModal();return;}modal(merchantProfile?'Edit business profile':'Set up your business',`<form id="business-form"><p class="muted small">Wallet connected · ${short(state.account)}</p><label for="business-name">Business display name</label><input id="business-name" maxlength="70" value="${esc(merchantProfile)}" placeholder="Olive Kitchen" required><div class="notice">Saved on this device for this wallet. Your next checkout can use this name.</div><button class="btn primary full" type="submit">Save business name ${icon('check')}</button></form>`);$('business-form').onsubmit=e=>{e.preventDefault();const name=$('business-name').value.trim();if(!name){toast('Enter your business name.');return;}merchantProfile=name;try{localStorage.setItem(profileKey(state.account),name);}catch{toast('Could not save on this device.');return;}$('modal').close();loadCurrent().catch(fail);toast('Business name saved for this wallet.');};}
function empty(title,description,action='create',label='Create a checkout'){return `<div class="empty-state"><span class="empty-icon">${icon('people')}</span><h2>${title}</h2><p>${description}</p>${btn(label,action,'primary','plus')}</div>`;}
function billCard(b){const pct=Number(b.raised*100n/b.target);return `<a class="checkout-card" href="#checkout/${b.id}"><div class="card-top"><div class="merchant-icon">${icon(b.people>1?'people':'store')}</div><span class="badge ${b.status}">${statusText(b)}</span></div><h3>${esc(b.title)}</h3><div class="card-sub">${esc(b.merchantName)} · #${b.id}</div><div class="card-amount">${fmt(b.raised)} <span>/ ${fmt(b.target)} USDC</span></div><div class="progress" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100" aria-label="Bill funded"><div style="width:${pct}%"></div></div><div class="card-meta"><span>${b.contributorCount} contributor${b.contributorCount===1?'':'s'}</span><span>${pct}%</span></div><div class="card-bottom"><span class="small muted">${b.status==='active'?new Date(Number(b.deadline)*1000).toLocaleDateString():statusText(b)}</span><span class="small">View bill ↗</span></div></a>`;}
function dashboard(kind='dashboard'){
 const list=state.bills.filter(b=>kind==='merchant'?b.merchant.toLowerCase()===state.account?.toLowerCase():kind==='refunds'?['expired','cancelled'].includes(b.status)&&b.contributors.some(c=>c.address.toLowerCase()===state.account?.toLowerCase()&&c.refund===0n):true);
 const active=list.filter(b=>b.status==='active'),paid=list.filter(b=>b.status==='paid');const filtered=filter==='all'?list:list.filter(b=>b.status===filter);
 const title=kind==='merchant'?'One checkout. Every customer.':kind==='refunds'?'Back where it belongs.':kind==='checkouts'?'Your checkouts.':'Money works better together.';
 shell(`${heading(title,kind==='refunds'?'Claim eligible contributions from expired or cancelled bills.':'Pay in full, split with friends, or receive USDC on Arc.',kind==='refunds'?'':btn('New checkout','create','primary','plus'))}${setupNotice()}${kind==='refunds'?'':`<div class="stats"><section class="stat"><div class="stat-head">Your USDC balance ${icon('wallet')}</div><div class="money">${state.balance===null?'—':fmt(state.balance)} <span class="unit">USDC</span></div><a class="stat-foot" href="#bridge">Add test funds ↗</a></section><section class="stat"><div class="stat-head">Active checkouts ${icon('bill')}</div><div class="money">${state.account?active.length:'—'}</div><div class="stat-foot">Among the ${state.bills.length} loaded checkouts</div></section><section class="stat"><div class="stat-head">Settled bill value ${icon('check')}</div><div class="money">${state.account?fmt(paid.reduce((s,b)=>s+b.target,0n)):'—'} <span class="unit">USDC</span></div><div class="stat-foot">Confirmed by the checkout contract</div></section></div>`}${!state.account?(kind==='dashboard'?welcomeWorkspace():empty('Connect to continue.','Connect your wallet to see the checkouts and payments linked to this address.','wallet','Connect wallet')):`<div class="section-head"><h2>${kind==='refunds'?'Claimable refunds':kind==='merchant'?'Merchant bills':'Recent checkouts'}</h2>${btn('Refresh','refresh','', 'clock')}</div><div class="tabs" role="group" aria-label="Filter checkouts">${(kind==='refunds'?[['all','All'],['expired','Expired'],['cancelled','Cancelled']]:[['all','All'],['active','Collecting'],['paid','Settled'],['expired','Expired'],['cancelled','Cancelled']]).map(([v,t])=>`<button class="${filter===v?'selected':''}" data-filter="${v}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div>${!state.loaded&&state.verified?'<div class="loading-state"><span class="spinner"></span> Reading your Arc checkouts…</div>':filtered.length?`<div class="cards">${filtered.map(billCard).join('')}</div>`:`<div class="activity-empty">${kind==='refunds'?'No claimable refunds among these loaded checkouts.':filter==='all'?'No checkouts in this view yet.':'No checkouts with this status.'}</div>`}${state.verified&&state.account&&state.bills.length<state.total?btn('Load older checkouts','older','','clock'):''}`}${kind==='dashboard'?`<div class="lower-grid"><section class="note-panel"><span class="eyebrow">ONE BILL. YOUR CHOICE.</span><h2>Pick up the bill. Or just your part.</h2><p>A customer can pay everything, contribute an equal share, or enter a custom amount. The merchant receives the full bill once it is funded.</p>${btn('Create a payment link','create','text','arrow')}</section><section class="note-panel white-note"><span class="eyebrow">SIMPLE TRANSFERS</span><h2>Just need to send?</h2><p>Send Circle USDC directly to an Arc wallet. Review the address, amount, and network fee before confirming.</p><a class="btn text" href="#send">Send USDC ${icon('arrow')}</a></section></div>`:''}`,kind);
 if(kind==='dashboard')document.querySelector('.lower-grid')?.insertAdjacentHTML('beforebegin',activityPanel());
 if(kind==='dashboard'&&!state.account){const welcome=document.querySelector('.welcome-workspace');document.querySelector('.quick-actions')?.before(welcome);}
 if(kind==='merchant')document.querySelector('.stats')?.insertAdjacentHTML('beforebegin',businessSetup());
}
function billView(b){currentBill=b;const mine=b.contributors.find(c=>c.address.toLowerCase()===state.account?.toLowerCase());const eligible=['expired','cancelled'].includes(b.status)&&mine&&mine.refund===0n;let suggested=paymentMode==='full'?b.remaining:paymentMode==='equal'?equalShare(b.target,b.people,mine?.amount||0n,b.remaining):0n;
 shell(`<a class="back" href="#${detailReturnRoute}">← ${detailReturnRoute==='history'?'Payment history':detailReturnRoute==='merchant'?'Business':detailReturnRoute==='refunds'?'Refunds':'All checkouts'}</a>${heading(esc(b.title),`Checkout #${b.id} · Read from Arc Testnet`,btn('Share QR','share','','link'))}<div class="checkout-layout"><section class="panel"><div class="bill-header"><div><span class="eyebrow muted">MERCHANT</span><h2>${esc(b.merchantName)}</h2>${explorer(b.merchant)}</div><div class="merchant-icon">${icon('store')}</div></div><div class="bill-total"><span>Total bill</span><span>${fmt(b.target)} <small>USDC</small></span></div><div class="bill-item"><span>Split suggestion</span><span>${b.people===1?'Pay in full':b.people+' people · equal or custom'}</span></div><div class="bill-item"><span>Deadline</span><span>${new Date(Number(b.deadline)*1000).toLocaleString()}</span></div><div class="notice">Merchant names are self-declared. Verify the recipient address before paying. Title, contributions, and wallet addresses are public on Arc.</div><div class="section-head"><h2>Contributions</h2><span class="badge ${b.status}">${statusText(b)}</span></div><div id="contributions">${b.contributors.length?b.contributors.map((c,i)=>`<div class="people-row"><span class="avatar">${i+1}</span><div class="name">${explorer(c.address)}${c.address.toLowerCase()===state.account?.toLowerCase()?' <span class="small muted">You</span>':''}<div class="small muted">${c.refund>0n?'Refund claimed':'Confirmed contribution'}</div></div><strong>${fmt(c.amount)} <span class="unit">USDC</span></strong></div>`).join(''):'<p class="muted small">Be the first to bring this bill together.</p>'}</div>${b.merchant.toLowerCase()===state.account?.toLowerCase()&&b.status==='active'?`<div class="notice">Need to stop this bill? Cancellation enables refunds for every contributor. Settled bills cannot be cancelled.</div>${btn('Cancel checkout','cancel','danger')}`:''}</section><aside class="panel payment-panel"><span class="eyebrow muted">${b.status==='paid'?'SETTLED WITH THE MERCHANT':'REMAINING TO PAY'}</span><div class="money">${fmt(b.status==='paid'?b.target:b.remaining)} <span class="unit">USDC</span></div><div class="progress"><div style="width:${Number(b.raised*100n/b.target)}%"></div></div><div class="card-meta"><span>${fmt(b.raised)} collected</span><span>${Number(b.raised*100n/b.target)}%</span></div>${b.status==='active'?`<div class="segmented" aria-label="Payment options">${[['full','Pay full'],['equal','My share'],['custom','Custom']].map(([v,t])=>`<button class="${paymentMode===v?'selected':''}" data-mode="${v}">${t}</button>`).join('')}</div><form id="pay-form"><label for="amount">Your payment · USDC</label><input name="amount" id="amount" inputmode="decimal" type="text" autocomplete="off" value="${suggested?fmt(suggested):''}" placeholder="0.00" ${paymentMode==='custom'?'':'readonly'} required><div class="fee-note">Network fees are additional, paid in USDC.<br>You will review an estimate before signing.</div><button class="btn primary" type="submit" ${state.busy?'disabled':''}>${state.account?'Review payment':'Connect wallet to pay'} ${icon('arrow')}</button></form><p class="disclaimer">Funds settle only when the full bill is covered. If it expires first, claim your contribution back.</p>`:b.status==='paid'?`<div class="notice">✓ Full bill settled on Arc Testnet.</div>${btn('Download receipt','receipt','primary','bill')}`:`<div class="notice">${mine?.refund>0n?'Your refund is confirmed.':eligible?`${fmt(mine.amount)} USDC is available to your connected wallet.`:state.account?'This wallet has no unclaimed contribution.':'Connect the contributing wallet to check your refund.'}</div>${state.account?eligible?btn('Claim my refund','refund','primary','shield'):'':btn('Connect wallet','wallet','primary')}`}<div class="payment-proof">${icon('shield')}<span>Contract-verified amounts<br>${explorer(state.registry,'View payment contract')}</span></div><div class="small muted last-sync">Updates every 12 seconds while visible.</div></aside></div>`,'checkouts');
 $('pay-form')?.addEventListener('submit',e=>{e.preventDefault();if(!state.account){walletModal();return;}run(()=>reviewPayment(parseAmount($('amount').value)));});
}
function modal(title,body){$('modal').innerHTML=`<div class="modal-title"><h2 id="dialog-title">${title}</h2><button class="round" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div id="modal-status" aria-live="polite"></div>${body}`;if(!$('modal').open)$('modal').showModal();updateStatus();}
function successReceipt(title,amount,detail,hash){return `<div class="success-receipt"><span class="success-mark">${icon('check')}</span><span class="success-label">CONFIRMED ON ARC TESTNET</span><div class="review-total">${esc(amount)} <span>USDC</span></div><p>${esc(detail)}</p><div class="success-network"><i></i><span><strong>Finalized on Arc</strong><small>Your wallet remains in control</small></span></div><a class="btn primary full" href="${EXPLORER}/tx/${encodeURIComponent(hash)}" target="_blank" rel="noopener noreferrer">View receipt on ArcScan ↗</a><button class="btn full" data-action="close">Done</button></div>`;}
function close(){if(state.busy){toast('Wait for the current wallet operation to finish.');return;}$('modal').close();}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5000);}
function fail(error){const text=error?.shortMessage||error?.message||'Something went wrong. Please try again.';state.error=text;updateStatus();toast(text);}
async function run(fn){state.error=null;updateStatus();try{return await fn();}catch(e){if($('modal').open&&$('modal').querySelector('.loading-state')&&!state.busy)$('modal').close();fail(e);}}
function walletModal(){if(state.account){modal('Your wallet',`<div class="wallet-summary"><span class="avatar">${icon('wallet')}</span><p class="address">${esc(state.account)}</p><h2>${state.balance===null?'—':fmt(state.balance)} USDC</h2><p class="muted small">${esc(state.walletName)} · ${state.chainId===5042002?'Arc Testnet ready':'Wrong network'}</p></div>${state.chainId!==5042002?btn('Add / switch to Arc','switch-network','primary','arrow'):''}<div class="modal-actions">${btn('Copy address','copy-wallet','')}${btn('Disconnect','disconnect','')}</div><a class="btn primary full" href="https://faucet.circle.com/" target="_blank" rel="noopener noreferrer">Get test USDC from Circle ↗</a>`);return;}const ps=getProviders();modal('Connect your wallet',`<div class="wallet-intro"><span class="wallet-shield">${icon('shield')}</span><div><strong>Connect securely</strong><p>Your keys stay in your wallet. Every payment needs your approval.</p></div></div><div class="wallet-list">${ps.map(p=>`<button class="btn wallet-choice" data-wallet="${esc(p.info.uuid)}"><span>${icon('wallet')}<strong>${esc(p.info.name)}</strong></span>${icon('arrow')}</button>`).join('')}${WC_PROJECT_ID?'<button class="btn wallet-choice" data-wallet="walletconnect"><span>'+icon('wallet')+'<strong>WalletConnect</strong></span>'+icon('arrow')+'</button>':''}</div>${!ps.length?'<div class="notice"><strong>No extension detected.</strong><br>Desktop: install or unlock MetaMask, Rabby, Coinbase Wallet, or another EVM wallet.<br>Phone: open this site inside your wallet app’s browser.</div>':''}<div class="network-preview"><i></i><span><strong>Arc Testnet</strong><small>Chain 5042002 · ${state.network?'RPC verified':'RPC check pending or unavailable'}</small></span><b>USDC</b></div><div class="fee-note">Testnet only. Arrey never asks for your seed phrase.</div>`);}
function createModal(){if(!state.account)return walletModal();if(!state.verified){location.hash='setup';return;}modal('Create a checkout',`<form id="create-form"><label for="title">What is the payment for?</label><input id="title" name="title" maxlength="70" required placeholder="Friday dinner"><label for="merchant">Business / recipient name</label><input id="merchant" name="merchant" maxlength="70" value="${esc(merchantProfile)}" required placeholder="Your business"><div class="form-grid"><div><label for="total">Total · USDC</label><input id="total" name="total" inputmode="decimal" required placeholder="3.00"></div><div><label for="people">People splitting</label><input id="people" name="people" type="number" min="1" max="100" step="1" value="3" required></div></div><label for="duration">Payment deadline</label><select id="duration" name="duration"><option value="900">15 minutes</option><option value="3600">1 hour</option><option value="86400" selected>24 hours</option><option value="604800">7 days</option></select><div class="notice">Payment goes to <strong>${esc(short(state.account))}</strong>. Checkout details are public and cannot be edited after creation. Set 1 person for a normal payment.</div><button class="btn primary full" data-financial type="submit">Create on Arc Testnet ${icon('arrow')}</button></form>`);$('create-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(async()=>{const title=String(f.get('title')).trim(),merchantName=String(f.get('merchant')).trim();if(!title||!merchantName||new TextEncoder().encode(title).length>120||new TextEncoder().encode(merchantName).length>120)throw Error('Use names between 1 and 120 UTF-8 bytes.');const people=Number(f.get('people'));if(!Number.isInteger(people)||people<1||people>100)throw Error('Choose 1–100 people.');const target=parseAmount(String(f.get('total'))),account=state.account;const id=await createBill({title,merchantName,target,duration:Number(f.get('duration')),people});const saved=recordConfirmed('created',id,target,title,state.hash,account);$('modal').close();location.hash='checkout/'+id;toast(saved?'Checkout confirmed on Arc. Share the QR to start collecting.':'Checkout confirmed on Arc. Local history was unavailable; your checkout is onchain.');});};}
async function reviewPayment(amount){const b=currentBill;if(!b)throw Error('Reload checkout.');modal('Review your payment','<div class="loading-state"><span class="spinner"></span> Checking bill and network fees…</div>');const estimate=await estimatePayment(b.id,amount);modal('Review your payment',`<div class="review-total">${fmt(amount)} <span>USDC</span></div><dl class="review-list"><div><dt>Merchant</dt><dd>${esc(b.merchantName)}</dd></div><div><dt>Recipient</dt><dd>${explorer(b.merchant)}</dd></div><div><dt>Network</dt><dd>Arc Testnet</dd></div><div><dt>Network fee ${estimate.estimated?'budget':'estimate'}</dt><dd>~${Number(estimate.gasUSDC).toFixed(6)} USDC</dd></div><div><dt>USDC approval</dt><dd>${estimate.approval?'One exact-amount approval first':'Already sufficient'}</dd></div></dl><p class="fee-note">${estimate.estimated?'The fee budget includes conservative approval/payment gas. Your wallet displays the final fee.':'Actual network fees may change before confirmation.'}</p><div class="notice">${amount===b.remaining?'This covers the remaining bill and settles with the merchant.':'This contribution stays in the checkout contract until fully funded, cancelled, or expired.'}</div><button class="btn primary full" id="confirm-payment" data-financial>Confirm payment in wallet ${icon('arrow')}</button>`);$('confirm-payment').onclick=()=>run(async()=>{const account=state.account;lastReceipt=await contribute(b.id,amount);const saved=recordConfirmed('contributed',b.id,amount,b.title,lastReceipt.transactionHash,account);await loadCurrent();if(!saved)toast('Payment confirmed. Local history was unavailable; ArcScan has the onchain receipt.');modal('Payment confirmed',successReceipt('Payment confirmed',fmt(amount),`Paid to ${b.merchantName}`,lastReceipt.transactionHash));});}
async function share(){if(!currentBill)return;const url=new URL(location.href);url.searchParams.set('registry',state.registry);const {default:QRCode}=await import('qrcode');const qr=await QRCode.toDataURL(url.href,{width:256,margin:2,errorCorrectionLevel:'M',color:{dark:'#203b33',light:'#ffffff'}});modal('One link. Everyone’s share.',`<div class="qr-space"><img src="${qr}" width="256" height="256" alt="QR code for checkout ${esc(currentBill.id)}"></div><label for="share-url">Checkout link</label><input id="share-url" value="${esc(url.href)}" readonly><button class="btn primary full" data-action="copy-link">Copy checkout link ${icon('link')}</button><p class="fee-note">Anyone with the link can read the bill. Contributors connect their own wallets to pay.</p>`);}
function sendView(){shell(`${heading('Send simply.','Transfer Circle USDC directly to an Arc Testnet wallet.')}<div class="checkout-layout"><section class="panel"><h2>A direct payment</h2><p class="intro-copy muted">For a friend, a supplier, or a one-off payment. Your wallet sends USDC directly to the recipient.</p><div class="notice">Direct transfers are final. Group checkout cancellation and refund rules do not apply.</div><a class="btn text" href="#dashboard">Need a shared bill? Create a checkout →</a></section><section class="panel payment-panel"><form id="send-form"><label for="recipient">Recipient wallet address</label><input id="recipient" name="recipient" placeholder="0x…" autocomplete="off" required><label for="send-amount">Amount · USDC</label><input id="send-amount" name="amount" inputmode="decimal" placeholder="1.00" required><p class="fee-note">Balance: ${state.balance===null?'Connect wallet':fmt(state.balance)+' USDC'}. Leave USDC for gas.</p><button class="btn primary full" ${state.account?'type="submit"':'type="button" data-action="wallet"'}>${state.account?'Review transfer':'Connect wallet'}</button></form></section></div>`,'send');$('send-form').onsubmit=e=>{e.preventDefault();if(!state.account)return walletModal();const to=$('recipient').value.trim();run(async()=>{const amount=parseAmount($('send-amount').value),fee=await estimateSend(to,amount);modal('Review direct transfer',`<div class="review-total">${fmt(amount)} <span>USDC</span></div><p class="address">To: ${esc(to)}</p><div class="notice">Arc Testnet · Estimated network fee ${Number(fee).toFixed(6)} USDC. This direct transfer cannot be cancelled or automatically refunded.</div><button class="btn primary full" id="confirm-send" data-financial>Confirm transfer in wallet</button>`);$('confirm-send').onclick=()=>run(async()=>{const from=state.account;const receipt=await sendUSDC(to,amount);const saved=saveTransfer({hash:receipt.transactionHash,from,to,amount});modal('Transfer confirmed',successReceipt('Transfer confirmed',fmt(amount),`Sent to ${short(to)}`,receipt.transactionHash));if(!saved)toast('Transfer confirmed. This device could not save its local receipt; ArcScan has the onchain record.');});});};}
function historyView(){
 const transfers=getTransfers(state.account),actions=getActions(state.account),bills=state.bills;
 const labels={created:'Created checkout',contributed:'Contributed',cancelled:'Cancelled checkout',refunded:'Claimed refund'};
 shell(`${heading('Payment history.','Confirmed Arc activity linked to this wallet.',state.account?btn('Refresh','refresh','','clock'):'')}${setupNotice()}${!state.account?'<div class="activity-empty">Connect your wallet to view your payment history.</div>':`
 <section class="activity-block"><div class="section-head"><h2>Recent actions on this device</h2></div>${actions.length?`<div class="activity-list">${actions.map(a=>`<a href="#action/${a.hash}"><span class="activity-symbol">${icon(a.type==='refunded'?'shield':a.type==='contributed'?'arrow':'bill')}</span><span><strong>${labels[a.type]}</strong><small>${new Date(a.recordedAt).toLocaleString()} · Checkout #${a.billId}${a.title?' · '+esc(a.title):''}</small></span><span class="activity-value"><strong>${a.amount?(a.type==='created'?'Target ':'')+fmt(a.amount)+' USDC':'Confirmed'}</strong><small>View details →</small></span></a>`).join('')}</div>`:'<div class="activity-empty">No checkout actions recorded by this device yet.</div>'}</section>
 <section class="activity-block"><div class="section-head"><h2>Linked checkouts</h2><span class="small muted">${state.verified?`${bills.length} of ${state.total} linked bills`:'Contract needed'}</span></div>${!state.verified?'<div class="activity-empty">Verify the checkout contract to read bills from Arc.</div>':!state.loaded?'<div class="loading-state"><span class="spinner"></span> Reading your Arc checkouts…</div>':bills.length?`<div class="activity-list">${bills.map(b=>`<a href="#checkout/${b.id}"><span class="activity-symbol">${icon(b.status==='paid'?'check':'bill')}</span><span><strong>${esc(b.title)}</strong><small>Checkout #${b.id} · ${esc(b.merchantName)} · ${statusText(b)}</small></span><span class="activity-value"><strong>${fmt(b.raised)} / ${fmt(b.target)} USDC</strong><small>View details →</small></span></a>`).join('')}</div>${bills.length<state.total?btn('Load older checkouts','older','', 'clock'):''}`:'<div class="activity-empty">No checkout activity for this wallet yet.</div>'}</section>
 <section class="activity-block"><div class="section-head"><h2>Direct transfers</h2><a class="small" href="${EXPLORER}/address/${encodeURIComponent(state.account)}" target="_blank" rel="noopener noreferrer">All wallet activity on ArcScan ↗</a></div>${transfers.length?`<div class="activity-list">${transfers.map(t=>`<a href="#transfer/${t.hash}"><span class="activity-symbol">${icon('arrow')}</span><span><strong>Sent USDC</strong><small>${new Date(t.recordedAt).toLocaleString()} · To ${short(t.to)}</small></span><span class="activity-value"><strong>${fmt(t.amount)} USDC</strong><small>Confirmed · View details →</small></span></a>`).join('')}</div>`:'<div class="activity-empty">No direct transfers recorded by Arrey on this device.</div>'}<p class="small muted">Action and transfer receipts are stored on this device. Linked checkout status comes from Arc; ArcScan is the complete transaction record.</p></section>`}`,'history');
}
function actionView(hash){const a=getActions(state.account).find(row=>row.hash.toLowerCase()===hash.toLowerCase());if(!a){shell(`${heading('Action unavailable.','Connect the wallet on the device that recorded this checkout action.')}<a class="btn" href="#history">Back to history</a>`,'history');return;}const labels={created:'Created checkout',contributed:'Contributed to checkout',cancelled:'Cancelled checkout',refunded:'Claimed refund'};shell(`<a class="back" href="#history">← Payment history</a>${heading(labels[a.type]+'.','Recorded after Arc confirmed the transaction.')}<section class="panel"><h2>Checkout #${a.billId} <span class="badge paid">Confirmed</span></h2><dl class="review-list"><div><dt>Action</dt><dd>${labels[a.type]}</dd></div>${a.title?`<div><dt>Checkout</dt><dd>${esc(a.title)}</dd></div>`:''}${a.amount?`<div><dt>${a.type==='created'?'Checkout total':'Amount'}</dt><dd>${fmt(a.amount)} USDC</dd></div>`:''}<div><dt>Recorded on this device</dt><dd>${new Date(a.recordedAt).toLocaleString()}</dd></div><div><dt>Wallet</dt><dd>${explorer(a.account)}</dd></div><div><dt>Transaction ID</dt><dd><a class="chain-link" href="${EXPLORER}/tx/${a.hash}" target="_blank" rel="noopener noreferrer">${short(a.hash)} ↗</a></dd></div></dl><a class="btn" href="#checkout/${a.billId}">View current checkout status ${icon('arrow')}</a></section>`,'history');}
function transferView(hash){const t=getTransfers(state.account).find(row=>row.hash.toLowerCase()===hash.toLowerCase());if(!t){shell(`${heading('Transfer unavailable.','Connect the sending wallet on the device that recorded this transfer.')}<a class="btn" href="#history">Back to history</a>`,'history');return;}shell(`<a class="back" href="#history">← Payment history</a>${heading('Direct transfer.','Recorded after Arc confirmed the transaction.')}<section class="panel"><h2>${fmt(t.amount)} USDC <span class="badge paid">Confirmed</span></h2><dl class="review-list"><div><dt>Transaction ID</dt><dd><a class="chain-link" href="${EXPLORER}/tx/${t.hash}" target="_blank" rel="noopener noreferrer">${short(t.hash)} ↗</a></dd></div><div><dt>Recorded on this device</dt><dd>${new Date(t.recordedAt).toLocaleString()}</dd></div><div><dt>From</dt><dd>${explorer(t.from)}</dd></div><div><dt>To</dt><dd>${explorer(t.to)}</dd></div><div><dt>Network</dt><dd>Arc Testnet</dd></div></dl></section>`,'history');}
function moreView(){shell(`${heading('More tools.','Funding, recovery, and network controls in one place.')}<div class="more-grid"><a class="panel more-card" href="#history"><span>${icon('clock')}</span><div><h2>History</h2><p>Review your linked checkouts and transfers.</p></div>${icon('arrow')}</a><a class="panel more-card" href="#refunds"><span>${icon('shield')}</span><div><h2>Refunds</h2><p>Claim eligible contributions from cancelled or expired checkouts.</p></div>${icon('arrow')}</a><a class="panel more-card" href="#bridge"><span>${icon('wallet')}</span><div><h2>Add funds</h2><p>Use Circle Faucet or bridge test USDC to Arc.</p></div>${icon('arrow')}</a><a class="panel more-card" href="#setup"><span>${icon('grid')}</span><div><h2>Network & contract</h2><p>Review Arc RPC, USDC, and checkout contract status.</p></div>${icon('arrow')}</a><a class="panel more-card" href="#landing"><span>${icon('home')}</span><div><h2>Arrey website</h2><p>Return to the product overview and guided demo.</p></div>${icon('arrow')}</a></div>`,'more');}
function setup(){shell(`${heading('Connected, with confidence.','Arc and Circle integration details for this testnet release.')}<div class="checkout-layout"><section class="panel"><h2>Network status</h2><dl class="review-list"><div><dt>Network</dt><dd>Arc Testnet · 5042002</dd></div><div><dt>RPC verification</dt><dd>${state.network?'Connected · USDC decimals verified':'Checking / unavailable'}</dd></div><div><dt>Settlement asset</dt><dd>Circle USDC · 6 decimals</dd></div><div><dt>Gas</dt><dd>Native USDC · 18 decimals</dd></div><div><dt>Checkout registry</dt><dd>${state.verified?explorer(state.registry):'Not configured'}</dd></div></dl><div class="notice">A single USDC balance pays both transfers and network fees. The app never counts native USDC and ERC-20 USDC as separate assets.</div><p class="intro-copy muted">Your checkout records live on Arc and can be read from any device. No seed phrases or private keys are stored by this website.</p><div class="reference-links"><a href="https://docs.arc.io/arc/references/connect-to-arc" target="_blank" rel="noopener noreferrer">Arc network docs ↗</a><a href="https://docs.arc.io/arc/references/contract-addresses" target="_blank" rel="noopener noreferrer">Circle USDC address ↗</a><a href="https://developers.circle.com/" target="_blank" rel="noopener noreferrer">Circle developer docs ↗</a></div></section><section class="panel"><h2>Checkout contract</h2><p class="muted intro-copy">Use the verified deployment, or deploy this exact testnet contract from your connected wallet.</p><form id="registry-form"><label for="registry">Existing contract address</label><input id="registry" name="registry" value="${esc(state.registry)}" placeholder="0x…" required><button class="btn full" data-financial type="submit">Verify & use contract</button></form><div class="notice">Only bytecode matching this app’s compiled contract is accepted. This is testnet software, not an audited mainnet payment product.</div><button class="btn primary full" data-action="deploy" data-financial>Deploy on Arc Testnet</button><p class="fee-note">Requires a funded Arc wallet and a wallet confirmation. Existing deployments do not need to be redeployed.</p></section></div>`,'setup');$('registry-form').onsubmit=e=>{e.preventDefault();run(async()=>{await setRegistry($('registry').value.trim());await loadCurrent();toast('Checkout contract verified.');});};}
async function bridgeView(){shell(`${heading('Bring your USDC along.','Fund your Arc wallet with Circle Faucet or bridge from another testnet.')}<div class="checkout-layout"><section class="panel"><span class="eyebrow muted">START HERE</span><h2 style="margin:12px 0">Free test funds</h2><p class="intro-copy muted">Request test USDC from Circle’s official faucet. Select Arc Testnet and paste your wallet address.</p>${state.account?`<p class="address">${esc(state.account)}</p>${btn('Copy wallet address','copy-wallet','')}`:''}<a class="btn primary full" href="https://faucet.circle.com/" target="_blank" rel="noopener noreferrer">Open Circle Faucet ↗</a><div class="notice">Test tokens have no monetary value. Circle controls faucet limits and CAPTCHA verification.</div></section><section class="panel payment-panel"><h2>Bridge to Arc</h2><p class="muted small" style="margin:12px 0 22px">Powered by Circle Bridge Kit & CCTP</p><form id="bridge-form"><label for="source-chain">From</label><select id="source-chain"><option value="Ethereum_Sepolia">Ethereum Sepolia</option><option value="Base_Sepolia">Base Sepolia</option></select><label>To</label><div class="network-box">Arc Testnet · your connected wallet</div><label for="bridge-amount">Amount · USDC</label><input id="bridge-amount" inputmode="decimal" placeholder="1.00" required><p class="fee-note">You need test ETH on the source chain and USDC for Arc gas. Bridging funds your wallet; paying a checkout is a separate step.</p><button class="btn primary full" ${state.account?'type="submit"':'type="button" data-action="wallet"'}>${state.account?'Review bridge costs':'Connect wallet'}</button></form><div id="bridge-progress"></div></section></div>`,'bridge');$('bridge-form').onsubmit=e=>{e.preventDefault();if(!state.account)return walletModal();run(async()=>{const source=$('source-chain').value,amount=fmt(parseAmount($('bridge-amount').value));modal('Estimate bridge costs','<div class="loading-state"><span class="spinner"></span> Asking Circle Bridge Kit for an estimate…</div>');bridgeModule??=await import('./bridge.js');const estimate=await bridgeModule.estimateBridge(source,amount);const fees=estimate.fees||[];modal('Review Circle bridge',`<div class="review-total">${esc(amount)} <span>USDC</span></div><p>${source==='Base_Sepolia'?'Base Sepolia':'Ethereum Sepolia'} → Arc Testnet</p><div class="notice">Protocol fees: ${fees.map(f=>esc(f.amount??'unavailable')+' '+esc(f.token)).join(', ')||'No protocol fee returned'}. Source and destination network gas is additional and shown in your wallet.</div><details><summary>Detailed gas estimate</summary><pre class="estimate-json">${esc(JSON.stringify(estimate.gasFees,(_,v)=>typeof v==='bigint'?v.toString():v,2))}</pre></details><p class="fee-note">Keep this page open during bridging. A completed source burn cannot be cancelled. If interrupted, resume the same transfer rather than starting another.</p><button class="btn primary full" id="confirm-bridge" data-financial>Bridge with Circle</button>`);$('confirm-bridge').onclick=()=>run(async()=>{try{await bridgeModule.bridge(source,amount);$('modal').close();toast('Circle bridge completed. Your Arc wallet is funded.');}finally{renderBridgeProgress();}});});};renderBridgeProgress();}
function renderBridgeProgress(){if(!bridgeModule)return;const s=bridgeModule.bridgeState;const el=$('bridge-progress');if(el)el.innerHTML=s.steps.length?`<h3 style="margin-top:24px">Bridge progress</h3>${s.steps.map(v=>`<div class="bill-item"><span>${esc(v.name)}</span><span>${esc(v.state)}${v.txHash?` · ${esc(short(v.txHash))}`:''}</span></div>`).join('')}${s.result&&s.result.state!=='success'?btn('Resume same bridge','retry-bridge',''):''}${!s.result&&s.steps.some(v=>v.txHash)?'<p class="notice">The result was interrupted. Check the saved transaction before starting another bridge.</p>':''}${s.result||s.steps.some(v=>v.txHash)?btn('Download recovery record','bridge-record',''):''}`:'';}
async function loadCurrent(){const token=++routeToken,hash=location.hash.slice(1)||'landing';if(hash==='landing'||hash==='home'||hash.startsWith('v2-')){landing();if(hash.startsWith('v2-'))requestAnimationFrame(()=>document.getElementById(hash)?.scrollIntoView());return;}currentBill=null;if(hash.startsWith('action/')){const tx=hash.slice(7);if(!/^0x[a-fA-F0-9]{64}$/.test(tx)){location.hash='history';return;}actionView(tx);return;}if(hash.startsWith('transfer/')){const tx=hash.slice(9);if(!/^0x[a-fA-F0-9]{64}$/.test(tx)){location.hash='history';return;}transferView(tx);return;}if(hash.startsWith('checkout/')){const id=hash.slice(9);if(!/^\d+$/.test(id)){shell(`${heading('That demo has moved on.','The old sample checkout is not a real testnet bill.')}<a class="btn primary" href="#dashboard">Open testnet workspace</a>`);return;}if(!state.verified){shell(`${heading('Open shared checkout','Verify the payment contract to read this bill.')}${setupNotice()}`,'checkouts');return;}try{const b=await loadBill(id);if(token===routeToken)billView(b);}catch(e){if(token===routeToken){shell(`${heading('Could not load this checkout.','Check the link or try again.')}<div class="notice">${esc(e.shortMessage||e.message)}</div>${btn('Try again','refresh','primary')}`,'checkouts');}}return;}
 if(!['setup','send','bridge','more','history','dashboard','checkouts','merchant','refunds'].includes(hash)){const url=new URL(location.href);url.hash='dashboard';history.replaceState(null,'',url);dashboard();return;}
 if(hash==='setup')setup();else if(hash==='send')sendView();else if(hash==='bridge')await bridgeView();else if(hash==='more')moreView();else if(hash==='history')historyView();else {const kind=['merchant','refunds','checkouts'].includes(hash)?hash:'dashboard';dashboard(kind);}if(state.verified&&state.account&&['dashboard','checkouts','merchant','refunds','history'].includes(hash))try{await loadBills();lastListRefresh=Date.now();if(token===routeToken){if(hash==='history')historyView();else dashboard(['merchant','refunds','checkouts'].includes(hash)?hash:'dashboard');}}catch(e){if(token===routeToken)fail(e);}
}
async function refreshBillSilently(){if(refreshing||state.busy||document.hidden||$('modal').open||!state.verified)return;const hash=location.hash;if(!currentBill&&Date.now()-lastListRefresh<45000)return;refreshing=true;try{if(currentBill){const id=currentBill.id;const b=await loadBill(id);if(hash!==location.hash)return;const signature=x=>JSON.stringify(x,(_,v)=>typeof v==='bigint'?v.toString():v);if(signature(b)!==signature(currentBill)){const draft=$('amount')?.value;billView(b);if(paymentMode==='custom'&&$('amount'))$('amount').value=draft||'';}}else if(state.account&&['#dashboard','#checkouts','#merchant','#refunds','#history'].includes(hash)){lastListRefresh=Date.now();await loadBills();if(hash===location.hash){if(hash==='#history')historyView();else dashboard(hash.slice(1));}}}catch(e){state.error='Could not refresh Arc status. Check the network before paying.';updateStatus();}finally{refreshing=false;}}
async function receipt(){if(!currentBill?.settled)return;const b=await loadBill(currentBill.id);if(!b.settled)throw Error('Settlement is not confirmed.');download('arrey-checkout-'+b.id+'.json',{network:'Arc Testnet',chainId:5042002,registry:state.registry,id:b.id,merchant:b.merchant,merchantName:b.merchantName,title:b.title,status:'settled',targetUSDC:fmt(b.target),raisedUSDC:fmt(b.raised),deadline:new Date(Number(b.deadline)*1000).toISOString(),contributors:b.contributors.map(c=>({wallet:c.address,USDC:fmt(c.amount)})),snapshotAt:new Date().toISOString(),source:'Contract state at download time; snapshotAt is not the settlement timestamp.'});}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,(_,v)=>typeof v==='bigint'?v.toString():v,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied.');}catch{toast('Clipboard unavailable. Select and copy the address or link.');}}
document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.wallet){run(async()=>{await connect(target.dataset.wallet);$('modal').close();await loadCurrent();});return;}if(target.dataset.filter){filter=target.dataset.filter;dashboard(location.hash.slice(1)||'dashboard');return;}if(target.dataset.mode){paymentMode=target.dataset.mode;billView(currentBill);return;}const action=target.dataset.action;if(!action)return;run(async()=>{if(action==='wallet')walletModal();if(action==='demo')demoModal();if(action==='demo-open'){close();location.hash='dashboard';}if(action==='onboarding')onboardingModal();if(action==='switch-network'){await addArcNetwork();walletModal();toast('Arc Testnet is ready.');}if(action==='disconnect'){disconnect();close();await loadCurrent();}if(action==='close')close();if(action==='create')createModal();if(action==='refresh'){state.error=null;await refreshWallet();await loadCurrent();}if(action==='older'){await loadBills({older:true});if(location.hash==='#history')historyView();else dashboard(['merchant','refunds','checkouts'].includes(location.hash.slice(1))?location.hash.slice(1):'dashboard');}if(action==='share')await share();if(action==='copy-link')await copy($('share-url').value);if(action==='copy-wallet'&&state.account)await copy(state.account);if(action==='receipt')await receipt();if(action==='deploy'){if(!state.account)return walletModal();await deployRegistry();await loadCurrent();toast('Contract deployed and verified.');}if(action==='cancel'){const id=currentBill.id;modal('Cancel this checkout?',`<p class="intro-copy">This permanently stops new contributions and lets each payer claim their own refund. It does not send refunds automatically.</p><button class="btn danger full" id="confirm-cancel" data-financial>Cancel on Arc Testnet</button>`);$('confirm-cancel').onclick=()=>run(async()=>{const bill=currentBill,account=state.account;const receipt=await cancelBill(id);recordConfirmed('cancelled',id,null,bill?.title,receipt.transactionHash,account);$('modal').close();await loadCurrent();});}if(action==='refund'){const bill=currentBill,account=state.account,amount=bill.contributors.find(c=>c.address.toLowerCase()===account?.toLowerCase())?.amount;const receipt=await refundBill(bill.id);const saved=recordConfirmed('refunded',bill.id,amount,bill.title,receipt.transactionHash,account);await loadCurrent();toast(saved?'Refund confirmed to your wallet.':'Refund confirmed. Local history was unavailable; ArcScan has the onchain receipt.');}if(action==='retry-bridge'){await bridgeModule.retryBridge();renderBridgeProgress();}if(action==='bridge-record')download('arrey-circle-bridge-recovery.json',{account:bridgeModule.bridgeState.account,result:bridgeModule.bridgeState.result,steps:bridgeModule.bridgeState.steps});});});
$('modal').addEventListener('cancel',e=>{if(state.busy)e.preventDefault();});window.addEventListener('hashchange',()=>{filter='all';paymentMode='full';lastReceipt=null;state.error=null;if($('modal').open&&!state.busy)$('modal').close();window.scrollTo(0,0);loadCurrent().catch(fail);});window.addEventListener('beforeunload',e=>{if(state.busy){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#v2-"]');if(!link)return;e.preventDefault();if(!document.querySelector('.v2-page')){location.hash='landing';requestAnimationFrame(()=>document.getElementById(link.hash.slice(1))?.scrollIntoView());return;}document.getElementById(link.hash.slice(1))?.scrollIntoView({behavior:'smooth'});});
document.addEventListener('click',e=>{if(!e.target.closest('a[href^="#checkout/"]'))return;const route=location.hash.slice(1);detailReturnRoute=route.startsWith('action/')?'history':['history','refunds','merchant'].includes(route)?route:'checkouts';});
subscribe(renderBridgeProgress);landing();loadCurrent().catch(fail);
Promise.allSettled([checkNetwork(),initRegistry()]).then(results=>{for(const result of results)if(result.status==='rejected')fail(result.reason);loadCurrent().catch(fail);});
poll=setInterval(refreshBillSilently,12000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshBillSilently();});
document.querySelector('.skip-link')?.addEventListener('click',e=>{e.preventDefault();const main=$('main-content');main?.setAttribute('tabindex','-1');main?.focus();});
try{if(sessionStorage.getItem('arrey-circle-recovery-v1')||localStorage.getItem('arrey-circle-recovery-v1'))import('./bridge.js').then(module=>{bridgeModule=module;renderBridgeProgress();}).catch(()=>{});}catch{}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_payment_workspace',description:'Read connected wallet and contract verification status. Does not request signatures or move funds.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({network:'Arc Testnet',connected:!!state.account,registry:state.registry,verified:state.verified,checkout:currentBill?{id:currentBill.id,status:currentBill.status,remainingUSDC:fmt(currentBill.remaining)}:null})});document.modelContext.registerTool({name:'open_checkout',description:'Read and open an existing Arc checkout by ID. Does not pay or connect a wallet.',inputSchema:{type:'object',properties:{id:{type:'string',pattern:'^[0-9]+$'}},required:['id'],additionalProperties:false},execute:async input=>{if(!/^\d+$/.test(input?.id||''))throw Error('Invalid checkout ID');const b=await loadBill(input.id);location.hash='checkout/'+b.id;billView(b);return{id:b.id,status:b.status};}});}catch{}}

